#!/usr/bin/env node
/**
 * Builds the generated half of the demo sites into `site/public/demos/_shared/`:
 *
 *   runtime.js           the sandbox's recording publicApi, from site/src/lib/demoRuntime.ts
 *   plugins/<name>.js    each plugin's built CDN bundle, copied from packages/*\/dist
 *   fixtures/<name>.js   each plugin's recorded fixtures, as `DDRumDemoFixtures['<name>']`
 *
 * The demos dispatch platform events built from those fixtures through the real bundle, so what
 * the sandbox shows is what a merchant's page would run. All three are gitignored: they are
 * build output, and committing them would let a demo run a stale plugin.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { build } from 'vite'
import { fromRoot } from './repo-root.mjs'

const outDir = fromRoot('site/public/demos/_shared')
mkdirSync(join(outDir, 'plugins'), { recursive: true })
mkdirSync(join(outDir, 'fixtures'), { recursive: true })

await build({
  configFile: false,
  logLevel: 'warn',
  root: fromRoot('site'),
  // The output lands inside site/public, so Vite must not also copy public into it.
  publicDir: false,
  build: {
    target: 'es2019',
    minify: true,
    sourcemap: false,
    emptyOutDir: false,
    outDir,
    lib: {
      entry: fromRoot('site/src/lib/demoRuntime.ts'),
      formats: ['iife'],
      name: 'DDRumSandbox',
      fileName: () => 'runtime.js',
    },
  },
})

const built = []
for (const dir of readdirSync(fromRoot('packages')).sort()) {
  if (!dir.startsWith('plugin-')) continue
  const name = dir.replace(/^plugin-/, '')
  const bundle = fromRoot('packages', dir, 'dist/plugin.js')
  if (!existsSync(bundle)) {
    console.error(`${bundle} not found — run "npm run build" first`)
    process.exit(1)
  }
  // The bundle's sourceMappingURL names plugin.js.map, which is not copied: drop the comment
  // rather than point a browser at a missing file.
  writeFileSync(join(outDir, 'plugins', `${name}.js`), readFileSync(bundle, 'utf8').replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, '\n'))

  const fixturesDir = fromRoot('packages', dir, 'fixtures')
  const byName = {}
  for (const file of readdirSync(fixturesDir).filter((entry) => entry.endsWith('.json')).sort()) {
    const parsed = JSON.parse(readFileSync(join(fixturesDir, file), 'utf8'))
    for (const fixture of Array.isArray(parsed) ? parsed : parsed.fixtures) byName[fixture.name] = fixture
  }
  writeFileSync(
    join(outDir, 'fixtures', `${name}.js`),
    `// Generated by scripts/build-demos.mjs from packages/${dir}/fixtures. Do not edit.\n` +
      `;(window.DDRumDemoFixtures = window.DDRumDemoFixtures || {})[${JSON.stringify(name)}] = ${JSON.stringify(byName)}\n`,
  )
  built.push(name)
}

console.log(`demos: runtime.js, plus bundles and fixtures for ${built.join(', ')}`)
